function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 10) return 'n is an integer from 1 to 10.';
  if (!Number.isInteger(k) || k < 1 || k > 9) return 'k is an integer from 1 to 9.';
  return null;
}

