function countGoodIntegers(n, k) {
  const factorial = [1];
  for (let i = 1; i <= n; i++) {
    factorial.push(factorial[i - 1] * i);
  }
  const halfLength = Math.ceil(n / 2);
  const counted = new Set();
  let total = 0;
  for (let half = 10 ** (halfLength - 1); half < 10 ** halfLength; half++) {
    const front = String(half);
    const paired = front.slice(0, n - halfLength);
    const key = paired.split('').sort().join('') + front.slice(n - halfLength);
    if (counted.has(key)) {
      continue;
    }
    const palindrome = front + paired.split('').reverse().join('');
    if (Number(palindrome) % k !== 0) {
      continue;
    }
    counted.add(key);
    const count = new Array(10).fill(0);
    for (const digit of palindrome) {
      count[Number(digit)]++;
    }
    let repeats = 1;
    for (const c of count) {
      repeats *= factorial[c];
    }
    total += (n - count[0]) * factorial[n - 1] / repeats;
  }
  return total;
}

