function countGoodIntegers(n, k) {
  // All distinct orders of the characters in text.
  const orders = (text) => {
    if (text.length <= 1) return [text];
    const result = new Set();
    for (let i = 0; i < text.length; i++) {
      for (const rest of orders(text.slice(0, i) + text.slice(i + 1))) result.add(text[i] + rest);
    }
    return [...result];
  };
  // Try every n-digit integer; integers with the same digits share one verdict.
  const verdict = new Map();
  let good = 0;
  for (let x = 10 ** (n - 1); x < 10 ** n; x++) {
    const digits = String(x).split('').sort().join('');
    if (!verdict.has(digits)) {
      verdict.set(digits, orders(digits).some(p => p[0] !== '0' && p === p.split('').reverse().join('') && Number(p) % k === 0));
    }
    if (verdict.get(digits)) good++;
  }
  return good;
}

