function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // The brute force tries every n-digit integer, so small inputs keep n at most 4.
  const n = size === 'large' ? int(6, 10) : int(1, 4);
  return [n, int(1, 9)];
}
